class Result(object):
    '''The result of a parse() or search().

    Fixed results may be looked up using result[index]. Named results may be
    looked up using result['name'].
    '''
    def __init__(self, fixed, named, spans):
        self.fixed = fixed
        self.named = named
        self.spans = spans

    def __getitem__(self, item):
        if isinstance(item, slice):
            # Support slice access on fixed fields
            return Result(
                self.fixed[item],
                self.named,
                {k: v for k, v in self.spans.items() if k in list(range(len(self.fixed)))[item] or isinstance(k, str)}
            )
        if isinstance(item, int):
            return self.fixed[item]
        return self.named[item]

    def __contains__(self, item):
        """Check if item exists in the parsed results (fixed values or named values)."""
        return item in self.fixed or item in self.named.values()

    def __repr__(self):
        return '<%s %r %r>' % (self.__class__.__name__, self.fixed,
            self.named)

